1563	+/**
1564	+ * The run lists' rules (docs/PRD_VIEWER_UX.md 4.1, 6.3 and 6.4), without React so the unit tests import them: the workflow
1565	+ * title rule, how Runs home sorts rows into Needs you, Running and Recent, what a row says, the controller suffix of the
1566	+ * live chip with its 15 s debounce, and when the Now banner reads the served `activity` over the export.
1567	+ *
1568	+ * Every row renders from the run summary alone (B2 `activity`); no run detail is fetched for a row. A summary without
1569	+ * `activity` (a server before contract 1.5.0) says only its status and when it was updated: no finish, no duration and no
1570	+ * Needs-you grouping.
1571	+ */
1572	+import {
1573	+  controllerNotRunning, deriveNow, type ControllerReading, type ControllerState, type Now, type Situation,
1574	+} from '../../contracts/projects/triage.ts'
1575	+import type { RunActivity, RunDetail, RunSummary } from './api.ts'
1576	+import { GENERIC_WORKFLOW_NAME, STATUS_LABEL, type RunStatus } from './status.ts'
1577	+
1578	+/** Recent lists every run that finished in the last seven days (decisions.md). */
1579	+export const RECENT_WINDOW_MS = 7 * 24 * 60 * 60 * 1000
1580	+/** Runs home and the project page re-read their run lists this often. */
1581	+export const LISTS_POLL_MS = 15_000
1582	+/** How many controller readings a run page keeps; the debounce needs only the latest run of equal values. */
1583	+const READINGS_KEPT = 50
1584	+
1585	+const FINISHED: readonly RunStatus[] = ['succeeded', 'failed', 'cancelled']
1586	+/** The attention kinds that wait on the operator (6.4); `interrupted`, `paused` and `failed` are the run's own state. */
1587	+export const WAITING_KINDS = ['question', 'pane', 'approval'] as const
1588	+export type WaitingKind = (typeof WAITING_KINDS)[number]
1589	+
1590	+export const isFinished = (status: RunStatus) => FINISHED.includes(status)
1591	+const ms = (iso: string) => Date.parse(iso)
1592	+
1593	+// ---- The workflow title rule (4.1, reordered in decisions.md) -------------------------------------------------------
1594	+
1595	+/**
1596	+ * A workflow's title in cards, headings and crumbs: a workflow under the exporter's generic name ("Feature implementation")
1597	+ * is named by its latest run's feature, else by its id; any other name is the title. The fixture names are not generic,
1598	+ * so every existing title stays as it was.
1599	+ */
1600	+export function workflowTitle(workflow: { workflow_id: string; name: string }, latestFeature: string | null = null): string {
1601	+  if (workflow.name !== GENERIC_WORKFLOW_NAME) return workflow.name
1602	+  return latestFeature ?? workflow.workflow_id
1603	+}
1604	+
1605	+/** The run a workflow's title reads its feature from: the one updated last (lists are sorted that way, but pages are merged). */
1606	+export function latestRun<T extends Pick<RunSummary, 'updated_at' | 'run_id'>>(runs: readonly T[]): T | null {
1607	+  return runs.reduce<T | null>((latest, run) => (latest === null || ms(run.updated_at) > ms(latest.updated_at) ? run : latest), null)
1608	+}
1609	+
1610	+export const latestFeature = (runs: readonly RunSummary[]) => latestRun(runs)?.activity?.feature ?? null
1611	+
1612	+// ---- Runs home sections (4.1) -----------------------------------------------------------------------------------------
1613	+
1614	+/** The kind a run waits on the operator for, from the served activity only; null without activity. */
1615	+export function waitingKind(run: Pick<RunSummary, 'status' | 'activity'>): WaitingKind | null {
1616	+  const kind = run.activity?.attention?.kind
1617	+  if (!kind || isFinished(run.status)) return null
1618	+  return (WAITING_KINDS as readonly string[]).includes(kind) ? kind as WaitingKind : null
1619	+}
1620	+
1621	+/** When a finished run ended, for the Recent window and its order: the served finish, else (without activity) its last update. */
1622	+export const endedAt = (run: Pick<RunSummary, 'updated_at' | 'activity'>) => run.activity?.finished_at ?? run.updated_at
1623	+/** When a run last moved, for ordering live rows: the served last activity, else its last update. */
1624	+export const movedAt = (run: Pick<RunSummary, 'updated_at' | 'activity'>) => run.activity?.last_activity_at ?? run.updated_at
1625	+
1626	+export type HomeSections<T> = { needsYou: T[]; running: T[]; recent: T[] }
1627	+
1628	+/**
1629	+ * Sorts rows into the three sections of Runs home; a run appears in one section only. Needs you: a question, a pane or an
1630	+ * approval waits (served `activity.attention.kind`), longest waiting first. Running: every other run that is not finished,
1631	+ * latest activity first. Recent: finished runs that ended within the seven days before `now`, newest first; older ones
1632	+ * stay on their project page only.
1633	+ */
1634	+export function homeSections<T extends { run: RunSummary }>(rows: readonly T[], now: number): HomeSections<T> {
1635	+  const needsYou: T[] = []
1636	+  const running: T[] = []
1637	+  const recent: T[] = []
1638	+  for (const row of rows) {
1639	+    if (waitingKind(row.run) !== null) needsYou.push(row)
1640	+    else if (!isFinished(row.run.status)) running.push(row)
1641	+    else if (ms(endedAt(row.run)) >= now - RECENT_WINDOW_MS) recent.push(row)
1642	+  }
1643	+  const since = (row: T) => ms(row.run.activity?.attention?.since ?? movedAt(row.run))
1644	+  needsYou.sort((a, b) => since(a) - since(b) || a.run.run_id.localeCompare(b.run.run_id))
1645	+  running.sort((a, b) => ms(movedAt(b.run)) - ms(movedAt(a.run)) || a.run.run_id.localeCompare(b.run.run_id))
1646	+  recent.sort((a, b) => ms(endedAt(b.run)) - ms(endedAt(a.run)) || a.run.run_id.localeCompare(b.run.run_id))
1647	+  return { needsYou, running, recent }
1648	+}
1649	+
1650	+/** Whether Runs home reads the next page of a workflow's runs: pages are newest first, so it stops at the Recent cutoff. */
1651	+export function readsNextPage(runs: readonly Pick<RunSummary, 'updated_at'>[], nextCursor: string | null, cutoff: number): boolean {
1652	+  const last = runs.at(-1)
1653	+  return nextCursor !== null && last !== undefined && ms(last.updated_at) >= cutoff
1654	+}
1655	+
1656	+// ---- Row wording (4.1, 6.4) --------------------------------------------------------------------------------------------
1657	+
1658	+/** The lane a launch node belongs to (`launch_<lane>`), else the node id itself (a reviewer's `review`). */
1659	+function who(nodeId: string | null): string {
1660	+  if (nodeId === null) return 'a step'
1661	+  return nodeId.startsWith('launch_') ? nodeId.slice('launch_'.length) : nodeId
1662	+}
1663	+
1664	+/**
1665	+ * A row's second line: what waits on the operator for a Needs-you row, else the status at the focus step with its last
1666	+ * message (the served headline, which starts with the focus label). Without activity it is only the status; the row then
1667	+ * shows when the run was updated and nothing else.
1668	+ */
1669	+export function rowSummary(run: Pick<RunSummary, 'status' | 'activity'>, labels: ReadonlyMap<string, string> = new Map()): string {
1670	+  const status = STATUS_LABEL[run.status]
1671	+  const activity = run.activity
1672	+  if (!activity) return status
1673	+  const kind = waitingKind(run)
1674	+  const node = activity.attention?.node_id ?? null
1675	+  if (kind === 'question') return `${who(node)} asked a question · deadline paused`
1676	+  if (kind === 'pane') return `${who(node)} needs attention in its pane`
1677	+  if (kind === 'approval') return `${node === null ? 'A step' : labels.get(node) ?? node} awaits your decision`
1678	+  const { focus, headline } = activity
1679	+  if (focus && (run.status === 'failed' || run.status === 'paused' || run.status === 'cancelled')) {
1680	+    const at = headline && headline.startsWith(focus.label) ? headline : headline ? `${focus.label} · ${headline}` : focus.label
1681	+    return `${status} at ${at}`
1682	+  }
1683	+  return headline ? `${status} · ${headline}` : status
1684	+}
1685	+
1686	+/** A row's time: a finished run's end and its duration, a live run's start and its elapsed time, or (without activity) only its last update. */
1687	+export type RowTime =
1688	+  | { kind: 'finished'; at: string; ms: number }
1689	+  | { kind: 'live'; started: string; last: string | null; ms: number }
1690	+  | { kind: 'updated'; at: string }
1691	+
1692	+export function rowTime(run: Pick<RunSummary, 'status' | 'created_at' | 'updated_at' | 'activity'>, now: number): RowTime {
1693	+  const activity = run.activity
1694	+  if (!activity) return { kind: 'updated', at: run.updated_at }
1695	+  if (activity.finished_at !== null) return { kind: 'finished', at: activity.finished_at, ms: Math.max(0, ms(activity.finished_at) - ms(run.created_at)) }
1696	+  if (isFinished(run.status)) return { kind: 'updated', at: run.updated_at }
1697	+  return { kind: 'live', started: run.created_at, last: activity.last_activity_at, ms: Math.max(0, now - ms(run.created_at)) }
1698	+}
1699	+
1700	+/** A project card's secondary text: how many features it registers and when its latest run last moved. */
1701	+export function projectFacts(workflows: number, runs: readonly Pick<RunSummary, 'updated_at' | 'activity'>[]): { features: string; lastRun: string | null } {
1702	+  const last = runs.reduce<string | null>((latest, run) => (latest === null || ms(movedAt(run)) > ms(latest) ? movedAt(run) : latest), null)
1703	+  return { features: `${workflows} ${workflows === 1 ? 'feature' : 'features'}`, lastRun: last }
1704	+}
1705	+
1706	+// ---- Controller liveness (6.3) -----------------------------------------------------------------------------------------
1707	+
1708	+/** Adds one poll's `activity.controller` reading; the list stays short, and an older reading never follows a newer one. */
1709	+export function recordReading(readings: readonly ControllerReading[], reading: ControllerReading): ControllerReading[] {
1710	+  const last = readings.at(-1)
1711	+  if (last && ms(last.at) > ms(reading.at)) return [reading]
1712	+  return [...readings, reading].slice(-READINGS_KEPT)
1713	+}
1714	+
1715	+export type ControllerSuffix = 'running' | 'not_running' | null
1716	+
1717	+/**
1718	+ * The live chip's controller suffix, shown only while the run is running or paused: `running` as soon as it is served;
1719	+ * `not_running` only once the readings have said so for 15 s, since one reading can be a checkpoint hand-over; nothing
1720	+ * for `unknown`, null or no reading, because the viewer never claims liveness it cannot check.
1721	+ */
1722	+export function controllerSuffix(status: RunStatus, readings: readonly ControllerReading[]): ControllerSuffix {
1723	+  if (status !== 'running' && status !== 'paused') return null
1724	+  const latest: ControllerState = readings.at(-1)?.value ?? null
1725	+  if (latest === 'running') return 'running'
1726	+  if (latest === 'not_running' && controllerNotRunning(readings)) return 'not_running'
1727	+  return null
1728	+}
1729	+
1730	+// ---- The Now banner and the served activity (6.2, 6.4) -----------------------------------------------------------------
1731	+
1732	+/** What the run page knows beyond its export: the served activity, the run directory and the controller readings. */
1733	+export type ServedRun = { detail: RunDetail; activity: RunActivity | null; runDir: string | null; controller: readonly ControllerReading[] }
1734	+
1735	+/** Situations that come before rule 5 (c): a stopped controller never hides a question, a pane, an approval or a paused challenge. */
1736	+const BEFORE_INTERRUPTED: readonly Situation[] = ['question', 'pane_attention', 'awaiting_approval', 'challenge_paused', 'interrupted']
1737	+
1738	+/**
1739	+ * Why the export-derived Now disagrees with what the server reads live, or null when it does not:
1740	+ * - `question-answered`: the export still shows a waiting question that the lane's live `<lane>.questions.json` records as
1741	+ *   answered (served `waiting_questions` is 0);
1742	+ * - `question-asked`: the live record holds a waiting question the export does not show (C5: the export is not rewritten
1743	+ *   while the handoff waits);
1744	+ * - `controller-stopped`: the controller has read `not_running` for 15 s while the run is running (rule 5 case c).
1745	+ */
1746	+export function servedDisagreement(now: Now, served: ServedRun): 'question-answered' | 'question-asked' | 'controller-stopped' | null {
1747	+  const { activity } = served
1748	+  const status = served.detail.summary.status
1749	+  if (activity && !isFinished(status)) {
1750	+    const asked = activity.waiting_questions > 0 && activity.attention?.kind === 'question'
1751	+    if (now.situation === 'question' && !asked) return 'question-answered'
1752	+    const lane = activity.attention?.node_id ? who(activity.attention.node_id) : null
1753	+    if (asked && (now.situation !== 'question' || (lane !== null && now.lane !== lane))) return 'question-asked'
1754	+  }
1755	+  if (status === 'running' && controllerNotRunning(served.controller) && !BEFORE_INTERRUPTED.includes(now.situation)) return 'controller-stopped'
1756	+  return null
1757	+}
1758	+
1759	+/**
1760	+ * The Now banner's model once the served activity is read: the export's own when both agree, else the situation derived
1761	+ * from the served fields alone (the run's snapshot, `activity` and the controller readings). That derivation has no events,
1762	+ * so it names the served question, pane or stopped controller without the reason the export would add.
1763	+ */
1764	+export function servedNow(now: Now, served: ServedRun | null): Now {
1765	+  if (served === null || servedDisagreement(now, served) === null) return now
1766	+  return deriveNow({ detail: served.detail, events: [], inputs: null, activity: served.activity, controller: served.controller })
1767	+}
