/**
 * Helpers shared by the Projects viewer specs: URL builders, locators for the run view, the screenshot
 * attachment every scenario records, the per-test setup (isolated API up, mocks in worker mode) and the
 * redaction assertion used by the `paths-redacted` scenarios.
 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')
export const taskDetails = (page: Page) => page.getByTestId('task-details')

/** A launch node shows its task behind a disclosure, closed by default (PRD_VIEWER_CLARITY 4.2); this opens it. */
export async function openTask(page: Page) {
  await expect(taskDetails(page)).toBeVisible()
  if ((await taskDetails(page).getAttribute('open')) === null) await taskDetails(page).locator('summary').first().click()
  await expect(taskDetails(page)).toHaveAttribute('open', '')
}

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}

/**
 * The fixture extension point of the viewer UX slices (docs/PRD_VIEWER_UX.md section 11). Each slice adds its runs in its
 * own module, `ux-<slice>.ts`, as a new workflow `ux-<slice>` appended after every workflow of `PROJECT`, so the existing
 * counts (two projects, five runs in `feature-flow`) do not change:
 * - `payloads`: the contract payloads the worker-phase mocks serve. This module spreads them into the maps `fixtures.ts`
 *   exports when it is first imported; `mock.ts` imports it, so they are merged before any request is served.
 * - `seed`: writes the same logical runs for the candidate phase and returns their registry entries; `seedCandidate`
 *   calls every module's seed with a `SeedContext`, appends the entries to `PROJECT`'s workflows and adds any top-level
 *   registry keys a module returns (S6's `viewer.expose_run_dir`, once the server accepts it).
 * After S1 no slice edits `fixtures.ts`, `mock.ts` or `seed.ts`: a slice changes only its own module. Modules import the
 * builders `fixtures.ts` exports and only types from here and from `seed.ts`, so no import cycle exists.
 */
import type { ReviewResult, RunDetail, RunInputs, WorkflowDefinition } from '../../../contracts/projects/v1.ts'
import type { WorkerResult, WorkflowEvent } from '../../../contracts/workflow/v1.ts'
import {
  artifactFiles, PROJECT, reviewResults, runDetails, runEvents, runInputs, runLists, workerResults, workflowLists,
  type ArtifactFile, type DefinitionNode,
} from '../fixtures.ts'
import type { SeedContext } from '../seed.ts'
import { uxLaunch } from './ux-launch.ts'
import { uxLists } from './ux-lists.ts'
import { uxNode } from './ux-node.ts'
import { uxReview } from './ux-review.ts'
import { uxRun } from './ux-run.ts'
import { uxTime } from './ux-time.ts'
import { uxVerify } from './ux-verify.ts'

/** A module's worker-phase payloads, keyed like the maps of `fixtures.ts`; run lists are derived from `runDetails`. */
export type UxPayloads = {
  /** Registered after every existing workflow of `PROJECT`, in module order. */
  workflows: WorkflowDefinition[]
  runDetails: Record<string, RunDetail>
  runEvents: Record<string, WorkflowEvent[]>
  /** Per run, keyed `<node>/<attempt>` or `candidate_<lane>/<attempt>` like the results route. */
  workerResults: Record<string, Record<string, WorkerResult>>
  reviewResults: Record<string, ReviewResult>
  runInputs: Record<string, RunInputs>
  artifactFiles: Record<string, ArtifactFile[]>
}

/** One registry workflow entry, as `seedCandidate` writes them. */
export type RegistryWorkflow = { workflow_id: string; runs_root: string; definition: { name: string; nodes: DefinitionNode[] } }

/** What a module's candidate-phase seed adds to the registry. */
export type UxSeed = {
  workflows: RegistryWorkflow[]
  /** Top-level registry keys beside `version` and `projects`; a later module's key replaces an earlier one's. */
  registry?: Record<string, unknown>
}

export type UxFixtureModule = {
  payloads?: Partial<UxPayloads>
  seed?: (context: SeedContext) => UxSeed
}

/** In slice order; the order the added workflows are listed in, in both phases. */
export const UX_FIXTURE_MODULES: readonly UxFixtureModule[] = [uxTime, uxRun, uxNode, uxVerify, uxLaunch, uxReview, uxLists]

function mergePayloads(modules: readonly UxFixtureModule[]) {
  for (const { payloads = {} } of modules) {
    const workflows = payloads.workflows ?? []
    workflowLists[PROJECT.project_id].workflows.push(...workflows)
    Object.assign(runDetails, payloads.runDetails)
    Object.assign(runEvents, payloads.runEvents)
    Object.assign(workerResults, payloads.workerResults)
    Object.assign(reviewResults, payloads.reviewResults)
    Object.assign(runInputs, payloads.runInputs)
    Object.assign(artifactFiles, payloads.artifactFiles)
    // The mocks index these per run: a run without events, results or artifacts serves none rather than failing.
    for (const runId of Object.keys(payloads.runDetails ?? {})) {
      runEvents[runId] ??= []
      workerResults[runId] ??= {}
      artifactFiles[runId] ??= []
    }
    // Each workflow's runs sorted by `updated_at` descending then `run_id` ascending, as the contract requires.
    for (const workflow of workflows) {
      runLists[workflow.workflow_id] = {
        runs: Object.values(runDetails).map(detail => detail.summary).filter(summary => summary.workflow_id === workflow.workflow_id)
          .sort((a, b) => b.updated_at.localeCompare(a.updated_at) || a.run_id.localeCompare(b.run_id)),
        next_cursor: null,
      }
    }
  }
}

mergePayloads(UX_FIXTURE_MODULES)

/** Seeds every module's runs for the candidate phase; returns what to add to the registry, in module order. */
export function seedUxFixtures(context: SeedContext): Required<UxSeed> {
  const seeded = UX_FIXTURE_MODULES.map(module => module.seed?.(context) ?? { workflows: [] })
  return {
    workflows: seeded.flatMap(seed => seed.workflows),
    registry: Object.assign({}, ...seeded.map(seed => seed.registry ?? {})) as Record<string, unknown>,
  }
}

import { useCallback, useMemo, type ReactNode } from 'react'
import { attemptResultUris, type Now, type Timeline } from '../../contracts/projects/triage.ts'
import { fetchReviewResult, paths, scopedResultPath, scopedReviewPath, type RunDetail, type RunInputs, type RunScope, type WorkerResult, type WorkflowEvent } from './api.ts'
import { ChallengeHeadline } from './Challenge.tsx'
import { ChallengeSections } from './node/ChallengeSections.tsx'
import { AwaitingNotice, ControllerSections } from './node/ControllerSections.tsx'
import { launchSectionEntries } from './node/launch.ts'
import { attemptStrip, causeOf, nodeTiming, resultRole, revisionAttempt, verifiedSections, type SectionEntry } from './node/model.ts'
import { challengeSectionEntries, reviewSectionEntries } from './node/panels.ts'
import { ReviewSections } from './node/ReviewSections.tsx'
import { CandidateLanes, VerifiedEvidence, WorkerReportLink, type LaneEntry } from './node/VerifySections.tsx'
import { WorkerSections } from './node/WorkerSections.tsx'
import { NodeHeader } from './NodeHeader.tsx'
import { AppLink, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { attemptPathname, runPathname } from './routes.ts'
import { NodeSection, SectionIndex } from './SectionIndex.tsx'
import { isChallengeNode } from './status.ts'
import { Time } from './Time.tsx'
import { useResource, type Resource } from './useResource.ts'
import { useRunResult, useRunResults } from './useRunData.ts'
import './node.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]

type Props = {
  scope: RunScope
  detail: RunDetail
  definition: DefinitionNode
  node: SnapshotNode
  /** The attempt the path names (`/attempts/<k>`); null shows the latest. */
  attempt: number | null
  events: Resource<WorkflowEvent[]>
  onRetryEvents: () => void
  /** The run's inputs (null once loaded when the export predates them), shared by every node of the run. */
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  /** The run's timeline, once its events loaded: the header's times, attempts and markers. */
  timeline: Timeline | null
  /** The run's situation, once derived: its next step is repeated on the focus node. */
  now: Now | null
  clock: number
  refreshToken: number
  onNavigate: (pathname: string) => void
  /** A requirement quote to highlight in this node's task, handed over by a review finding link. */
  highlight: string | null
  onHighlightApplied: () => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  /** A captured file to scroll to on this launch node, handed over by a review finding's file link. */
  fileFocus: string | null
  onFileFocusApplied: () => void
  onOpenFile: (nodeId: string, path: string) => void
}

/**
 * One node of a run (docs/PRD_VIEWER_UX.md 4.4-4.9): the header (status by cause, timing, attempts, next step), a section
 * index with counts, then the sections of its kind (worker, verification, candidate, review, challenge or the controller's
 * own steps) and History, always last. Empty sections are absent; a result the launch and verify nodes share is said once.
 * An earlier attempt's page shows that attempt's own result under a banner that leads back to the latest.
 */
export function NodeDetail({ scope, detail, definition, node, attempt, events, onRetryEvents, inputs, onRetryInputs, timeline, now, clock, refreshToken, onNavigate, highlight, onHighlightApplied, onOpenRequirement, fileFocus, onFileFocusApplied, onOpenFile }: Props) {
  const definitionNodes = detail.definition.nodes
  const snapshotNodes = detail.snapshot.nodes

  const isWorker = definition.kind === 'worker'
  const isChallenge = isChallengeNode(definition)
  const isReview = definition.kind === 'review' && !isChallenge
  const isCandidate = node.node_id === 'candidate'
  const isVerify = definition.kind === 'verification' && !isCandidate
  const isController = definition.kind === 'prepare' || definition.kind === 'integration'
  const isApproval = isController && node.node_id === 'approval'
  const latest = node.attempt
  const isLatest = attempt === null || attempt === latest
  const shownAttempt = attempt ?? latest
  const recorded = shownAttempt >= 1 && shownAttempt <= latest

  // What this view reads: the latest attempt's result as served, or the viewed attempt's own (`results/<lane>/<k>`).
  const attemptUris = useMemo(() => attemptResultUris(detail, node.node_id), [detail, node.node_id])
  const resultUri = definition.kind === 'review' ? null
    : isLatest || !isVerify ? node.result_uri
      : attemptUris.find(item => item.attempt === attempt)?.uri ?? null
  const lanes: LaneEntry[] = isLatest || !isCandidate ? node.lane_results
    : attemptUris.filter(item => item.attempt === attempt).map(item => ({ worker: item.lane, attempt: item.attempt, result_uri: item.uri }))
  const resultPath = resultUri === null ? null : scopedResultPath(scope, resultUri)
  const stamp = String(refreshToken)
  const { state: result, reload: reloadResult } = useRunResult(scope, resultPath, stamp)
  const resultData = result.status === 'ready' ? result.data : null

  // The attempt strip: a chip shows once one of its results loaded (read through the run's cache, asked again on new events).
  const strip = useMemo(() => (timeline ? attemptStrip(detail, timeline, node.node_id) : []), [detail, timeline, node.node_id])
  const chipUris = useMemo(() => strip.flatMap(item => (item.kind === 'attempt' ? item.chip.uris : [])), [strip])
  const { results: chipResults } = useRunResults(scope, chipUris, `${refreshToken}:${detail.snapshot.last_sequence}`)
  const loaded = useCallback((uri: string) => chipResults.has(uri), [chipResults])
  const viewedChip = strip.flatMap(item => (item.kind === 'attempt' && item.chip.attempt === shownAttempt ? [item.chip] : []))[0]

  // The candidate's own verdict is its lanes': a failing lane's gate reasons are the cause its header names.
  const { results: laneResults } = useRunResults(scope, useMemo(() => lanes.map(entry => entry.result_uri), [lanes]), stamp)
  const failure = lanes.flatMap(entry => {
    const error = laneResults.get(entry.result_uri)?.error
    return error ? [`${entry.worker}: ${error.message}`] : []
  }).join('; ') || null

  const nodeEvents = events.status === 'ready' ? events.data.filter(event => event.node_id === node.node_id) : []
  const reuse = nodeEvents.filter(event => event.type === 'result_reused')
  const approvals = nodeEvents.filter(event => event.type === 'approval_requested')

  const recordedInputs = inputs.status === 'ready' ? inputs.data : null
  const worker = isWorker && recordedInputs !== null ? recordedInputs.workers.find(candidate => candidate.launch_node_id === node.node_id) ?? null : null
  // The design challenge is also of kind review; the independent review is the other one.
  const reviewNode = snapshotNodes.find(candidate => candidate.kind === 'review' && !isChallengeNode(candidate)) ?? null

  // The recorded review, held here for the review's sections and index (Blocking N, Findings N) and the approval's bundle
  // (docs/PRD_VIEWER_UX.md 4.7, 4.9). The snapshot links it; an older export has no link, so the first attempt is asked for
  // once the node ran. The fallback path before a review is recorded equals the linked one after, so the key also names
  // what the node shows, and a review opened before its verdict is read again when the node's status changes.
  const reviewSource = isReview ? node : isApproval ? reviewNode : null
  const reviewPath = reviewSource === null ? null
    : reviewSource.result_uri !== null ? scopedReviewPath(scope, reviewSource.result_uri)
      : reviewSource.status === 'pending' ? null : paths.review(scope, Math.max(reviewSource.attempt, 1))
  const reviewUnscoped = isReview && node.result_uri !== null && reviewPath === null ? node.result_uri : null
  const loadReview = useCallback((signal: AbortSignal) => fetchReviewResult(scope, reviewPath!, signal), [scope, reviewPath])
  const { state: review, reload: reloadReview } = useResource(reviewPath === null ? null : `${reviewPath}|${reviewSource?.result_uri ?? reviewSource?.status}`, loadReview, refreshToken)
  const reviewData = review.status === 'ready' ? review.data : null
  // A review's executor wording depends on the transport its served result records.
  const reviewTransport = isReview ? reviewData?.reviewer.transport : undefined
  const hasNode = (nodeId: string) => definitionNodes.some(candidate => candidate.node_id === nodeId)
  const nodeLink = (nodeId: string) => ({ node_id: nodeId, href: runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId), label: definitionNodes.find(candidate => candidate.node_id === nodeId)!.label })
  const launchNodeOf = (lane: string) => {
    const launched = recordedInputs?.workers.find(candidate => candidate.node_id === lane)?.launch_node_id
    const id = launched && hasNode(launched) ? launched : hasNode(`launch_${lane}`) ? `launch_${lane}` : null
    return id === null ? null : nodeLink(id)
  }
  const lane = isWorker ? worker?.node_id ?? node.node_id.replace(/^launch_/, '') : null
  // A verification reads its lane's declared checks (they name the executed ones and key the gate's reasons) and requirements.
  const declaredOf = (id: string) => recordedInputs?.workers.find(candidate => candidate.node_id === id)?.checks ?? null
  const verifiedWorker = isVerify ? recordedInputs?.workers.find(candidate => candidate.node_id === node.node_id.replace(/^verify_/, '')) ?? null : null
  const verifyId = lane !== null && hasNode(`verify_${lane}`) ? `verify_${lane}` : null
  const verifyState = verifyId === null ? null : snapshotNodes.find(candidate => candidate.node_id === verifyId) ?? null
  const verifyNode = verifyId === null ? null : { ...nodeLink(verifyId), status: verifyState?.status ?? 'pending' as const, attempt: verifyState?.attempt ?? 0 }
  // What the worker handed over: the verification's first attempt ran on the snapshot frozen at handoff (a repair makes a new one).
  const frozenUri = verifyId === null ? null : attemptResultUris(detail, verifyId).find(item => item.attempt === 1)?.uri ?? null
  const { results: frozenResults } = useRunResults(scope, useMemo(() => (frozenUri === null ? [] : [frozenUri]), [frozenUri]), stamp)
  const frozen = frozenUri === null ? null : frozenResults.get(frozenUri) ?? null
  const frozenCommit = frozen?.output_commit ?? null
  const role = resultRole(detail, node.node_id)
  const reportNode = isVerify && !role.narrative && role.partner !== null ? nodeLink(role.partner) : null
  const repairs = (timeline?.markers ?? []).filter(marker => marker.kind === 'repair' && verifyNode !== null && marker.node_id === verifyNode.node_id)
  const repairLabel = repairs.length ? `repair ${repairs.map(marker => marker.repair?.n ?? '').filter(n => n !== '').join(', ')}`.trim() : ''
  const repairNote = repairLabel ? `after operator ${repairLabel}` : ''

  const timing = timeline && recorded ? nodeTiming(timeline, node.node_id, isLatest ? null : attempt, isVerify ? resultData : null) : null
  const headerStatus = isLatest ? node.status : viewedChip?.status ?? resultData?.status ?? 'pending'
  const cause = causeOf({
    timeline, nodeId: node.node_id, attempt: isLatest ? null : shownAttempt, events: nodeEvents, latest,
    error: headerStatus === 'failed' ? resultData?.error?.message ?? failure : null,
  })
  // A live or failed verification counts its attempts against the cap, which a repair restarts (5.3).
  const cap = recordedInputs?.max_verification_attempts ?? null
  const revision = (isVerify || isCandidate) && recorded && timeline !== null && cap !== null && (headerStatus === 'running' || headerStatus === 'failed')
    ? { attempt: revisionAttempt(timeline, node.node_id, shownAttempt), of: cap }
    : null
  // A failed verification also says what happens next when nothing is to be typed (it replaces the old retry note, 8).
  const failedCheck = (isVerify || isCandidate) && node.status === 'failed'
  // A launch node's waiting question carries its answer commands in its own first section; the header does not repeat them.
  const answered = isWorker && now?.situation === 'question' && now.lane === lane && (worker?.questions.some(question => question.answer === null) ?? false)
  const next = isLatest && !answered && now?.focus?.node_id === node.node_id && (now.next.steps.length > 0 || now.next.action === 'required' || failedCheck) ? now.next : null
  const attemptHref = (value: number) => attemptPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id, value)
  const nodeHref = runPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id)

  const renderResult = (evidence: (data: WorkerResult) => ReactNode) => (
    <>
      {resultUri === null && lanes.length === 0 && <p className="projects-muted" data-testid="result-none">No result has been published for this node{node.attempt === 0 ? ' (it has not started)' : ''}.</p>}
      {resultUri !== null && resultPath === null && (
        <p className="projects-error-inline" role="alert" data-testid="result-unscoped">
          The result link <code>{resultUri}</code> is outside this run's results route and was not fetched.
        </p>
      )}
      {resultPath !== null && result.status === 'loading' && <LoadingPanel>Loading the result…</LoadingPanel>}
      {resultPath !== null && result.status === 'error' && <ErrorPanel error={result.error} what="The node result" onRetry={reloadResult} />}
      {resultPath !== null && result.status === 'ready' && evidence(result.data)}
    </>
  )

  // The section index: what the kind lists, only when it lists something, then reuse (only with reuse events) and History.
  const sections: SectionEntry[] = [
    ...(isWorker ? launchSectionEntries(worker, frozen, resultData) : []),
    ...(isCandidate && lanes.length > 0 ? [{ key: 'lanes', label: 'Lanes', count: lanes.length }] : []),
    ...((isVerify || isCandidate) && resultData !== null ? verifiedSections(resultData, { requirements: verifiedWorker !== null }) : []),
    // A review or challenge that recorded nothing keeps only its honesty line, with no chip.
    ...(isReview ? reviewSectionEntries(reviewData) : []),
    ...(isChallenge ? challengeSectionEntries(recordedInputs?.challenge ?? null) : []),
    ...(reuse.length > 0 ? [{ key: 'reuse', label: 'Reuse', count: reuse.length }] : []),
    { key: 'history', label: 'History', ...(events.status === 'ready' ? { count: nodeEvents.length } : {}) },
  ]
  // An earlier attempt keeps only a verification's own result; any other step's earlier attempt shows its times and History.
  const evidence = isLatest || (recorded && (isVerify || isCandidate))

  return (
    <section className="node-detail" aria-labelledby="node-detail-title" data-testid="node-detail" data-node-id={node.node_id} data-attempt={isLatest ? undefined : shownAttempt}>
      <NodeHeader
        definition={definition}
        status={headerStatus}
        attempt={shownAttempt}
        timing={timing}
        clock={clock}
        cause={cause}
        revision={revision}
        timeline={timeline}
        reviewTransport={reviewTransport}
        verifyNode={verifyNode}
        strip={strip}
        loaded={loaded}
        attemptHref={attemptHref}
        next={next}
        onNavigate={onNavigate}
      />

      {!isLatest && (
        <p className="projects-notice attempt-banner" role="note" data-testid="attempt-banner">
          {recorded ? `You are viewing attempt ${attempt} of ${latest}. ` : `Attempt ${attempt} of this step was not recorded. `}
          <AppLink href={nodeHref} onNavigate={onNavigate}>{latest === 0 ? 'Open the step ›' : `The latest is attempt ${latest} ›`}</AppLink>
        </p>
      )}

      {isLatest && node.status === 'awaiting_approval' && <AwaitingNotice nodeId={node.node_id} approvals={approvals} events={nodeEvents} clock={clock} />}

      {isChallenge && isLatest && recordedInputs?.challenge && (
        <ChallengeHeadline challenge={recordedInputs.challenge} spans={timeline?.byNode.get(node.node_id) ?? []} />
      )}

      {!isController && (isLatest || recorded) && (
        <SectionIndex label={definition.label} sections={evidence ? sections : sections.filter(section => section.key === 'history')}>
          {reportNode && <WorkerReportLink href={reportNode.href} label={reportNode.label} onNavigate={onNavigate} />}
        </SectionIndex>
      )}

      {!evidence && recorded && <p className="projects-muted" data-testid="attempt-latest-only">Only the latest attempt's evidence is kept for this step; the times above are this attempt's.</p>}

      {evidence && (
        isWorker ? (
          <WorkerSections
            scope={scope}
            renderResult={renderResult}
            result={result}
            role={role}
            checksNode={verifyNode}
            frozen={frozen}
            frozenCommit={frozenCommit}
            repairNote={repairNote}
            repairLabel={repairLabel}
            answer={answered ? now.next : null}
            inputs={inputs}
            onRetryInputs={onRetryInputs}
            worker={worker}
            reviewNode={reviewNode}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            highlight={highlight}
            onHighlightApplied={onHighlightApplied}
            fileFocus={fileFocus}
            onFileFocusApplied={onFileFocusApplied}
          />
        ) : isChallenge ? (
          <ChallengeSections inputs={inputs} onRetryInputs={onRetryInputs} />
        ) : isReview ? (
          <ReviewSections
            scope={scope}
            review={review}
            onRetryReview={reloadReview}
            unscopedUri={reviewUnscoped}
            definitionNodes={definitionNodes}
            snapshotNodes={snapshotNodes}
            inputs={inputs}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            onOpenRequirement={onOpenRequirement}
            onOpenFile={onOpenFile}
          />
        ) : isController ? (
          <ControllerSections
            scope={scope}
            node={node}
            events={nodeEvents}
            spans={timeline?.byNode.get(node.node_id) ?? []}
            inputs={recordedInputs}
            review={reviewData}
            renderResult={renderResult}
          />
        ) : (
          <>
            {lanes.length > 0 && (
              <CandidateLanes
                scope={scope} lanes={lanes} launchNodeOf={launchNodeOf} declaredOf={declaredOf} timeline={timeline} cap={cap}
                repairLanes={isLatest && now?.situation === 'blocked_identical' && now.lane ? now.lane.split(',') : []}
                stamp={stamp} onNavigate={onNavigate}
              />
            )}
            {renderResult(data => (
              <VerifiedEvidence
                scope={scope} result={data} phase="worker" anchored
                declared={verifiedWorker?.checks ?? null}
                attemptStart={timing?.start?.at ?? null}
                requirements={verifiedWorker && { worker: verifiedWorker, cap: recordedInputs?.max_verification_attempts ?? null }}
              />
            ))}
          </>
        )
      )}

      {reuse.length > 0 && (
        <NodeSection sectionKey="reuse" title="Reuse evidence">
          <ul className="evidence-list" data-testid="reuse-list">
            {reuse.map(event => (
              <li key={event.event_id}>
                Attempt {event.attempt} reused the result of attempt {event.reused_from_attempt ?? 'unknown'} (event {event.sequence}, <Time iso={event.occurred_at} seconds />): {event.message}
              </li>
            ))}
          </ul>
        </NodeSection>
      )}

      <NodeSection sectionKey="history" title="History">
        {events.status === 'loading' && <LoadingPanel>Loading events…</LoadingPanel>}
        {events.status === 'error' && <ErrorPanel error={events.error} what="The run events" onRetry={onRetryEvents} />}
        {events.status === 'ready' && (nodeEvents.length === 0 ? (
          <p className="projects-muted" data-testid="events-none">No events reference this node.</p>
        ) : (
          <ol className="event-list" data-testid="node-events">
            {nodeEvents.map(event => (
              <li key={event.event_id} data-attempt={event.attempt}>
                <span className="event-seq">#{event.sequence}</span> <span className="projects-muted"><Time iso={event.occurred_at} seconds /></span>{' '}
                <span className="event-type">{event.type.replace(/_/g, ' ')}</span>
                {event.status && <> · <StatusBadge status={event.status} /></>}
                {event.attempt > 0 && <> · attempt {event.attempt}</>}
                {event.message && <> — {event.message}</>}
                {event.artifact && <> · artifact <code>{event.artifact.artifact_id}</code> ({event.artifact.kind})</>}
              </li>
            ))}
          </ol>
        ))}
      </NodeSection>
    </section>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { Resource } from './resource.ts'

export type { Resource } from './resource.ts'

/** How fresh a resource is (docs/PRD_VIEWER_UX.md 6.3): the live chip's ages, the Refresh button's busy state and the failed-Refresh notice read it. */
export type ResourceMeta = {
  /** When the shown data last loaded successfully (epoch milliseconds); null before the first success. */
  settledAt: number | null
  /** The error of the latest load while loads fail; null once one succeeds. */
  lastError: unknown
  /** Loads that failed since the last success; a failed background load keeps the data shown. */
  failures: number
  /** A Refresh is loading in the background while the previous value stays shown. */
  refreshing: boolean
  /** The error of a Refresh that failed while data was shown, until a later load succeeds; null otherwise. */
  refreshError: unknown
}

type Settled<T> = { base: string; refresh: number; value: Resource<T>; settledAt: number | null; lastError: unknown; failures: number; refreshError: unknown }

/**
 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
 * because every request is aborted once the next one starts, and a settled value is tagged with the key and attempt
 * that produced it.
 * `refreshToken` (the header Refresh button) and `pollToken` (live polling) both reload in the background: the last
 * settled value stays shown while it loads, and a failed reload keeps the last loaded data instead of replacing it with an
 * error. `meta` says when the data last loaded, how many loads failed since, whether a Refresh is still loading, and
 * whether the last Refresh failed, so the page can say that what it shows may be outdated.
 */
export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0, pollToken = 0): { state: Resource<T>; reload: () => void; meta: ResourceMeta } {
  const [settled, setSettled] = useState<Settled<T> | null>(null)
  const [attempt, setAttempt] = useState(0)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load }, [load])
  const base = key === null ? null : `${key}\u0000${attempt}`
  const token = base === null ? null : `${base}\u0000${refreshToken}\u0000${pollToken}`

  useEffect(() => {
    if (token === null || base === null) return
    const controller = new AbortController()
    loadRef.current(controller.signal).then(
      data => {
        if (controller.signal.aborted) return
        setSettled({ base, refresh: refreshToken, value: { status: 'ready', data }, settledAt: Date.now(), lastError: null, failures: 0, refreshError: null })
      },
      error => {
        if (controller.signal.aborted) return
        setSettled(previous => {
          const same = previous !== null && previous.base === base ? previous : null
          const failures = (same?.failures ?? 0) + 1
          // The first load to settle after a Refresh answers it; a failed poll keeps the outcome of the last Refresh.
          const answersRefresh = same !== null && same.refresh !== refreshToken
          return same !== null && same.value.status === 'ready'
            ? { ...same, refresh: refreshToken, lastError: error, failures, refreshError: answersRefresh ? error : same.refreshError }
            : { base, refresh: refreshToken, value: { status: 'error', error }, settledAt: same?.settledAt ?? null, lastError: error, failures, refreshError: null }
        })
      },
    )
    return () => controller.abort()
  }, [base, token, refreshToken])

  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
  const current = settled !== null && settled.base === base ? settled : null
  const state: Resource<T> = token === null ? { status: 'idle' } : current !== null ? current.value : { status: 'loading' }
  const meta: ResourceMeta = {
    settledAt: current?.settledAt ?? null,
    lastError: current?.lastError ?? null,
    failures: current?.failures ?? 0,
    refreshing: current !== null && current.refresh !== refreshToken,
    refreshError: current?.refreshError ?? null,
  }
  return { state, reload, meta }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Breadcrumbs, type PathCrumb } from '../graph/Breadcrumbs.tsx'
import type { ControllerReading } from '../../contracts/projects/triage.ts'
import {
  describeApiError, fetchProjects, fetchRegistryRuns, fetchRunDetail, fetchRuns, fetchWorkflowRuns, fetchWorkflows, ProjectsApiError,
  type RunPage, type RunSummary,
} from './api.ts'
import { latestFeature, LISTS_POLL_MS, readsNextPage, RECENT_WINDOW_MS, recordReading, workflowTitle, type ServedRun } from './lists.ts'
import './lists.css'
import { ServedRunContext } from './LiveStatus.tsx'
import { AppLink, EmptyPanel, ErrorPanel, LoadingPanel } from './panels.tsx'
import { projectPathname, projectsPathname, runPathname, workflowPathname, type ProjectsRoute } from './routes.ts'
import { RunRow } from './RunRow.tsx'
import { ProjectRunGroups, RunsHome } from './RunsHome.tsx'
